//! The WA Desk icon: one rasteriser output (`assets/icon.png`, generated by
//! `cargo run -p wa-desktop-native --example gen_icon`) used for the window and
//! taskbar; `assets/icon.ico` is embedded in the exe by `build.rs`.

/// The window/taskbar icon handed to `eframe`.
pub fn window_icon() -> egui::IconData {
    let bytes = include_bytes!("../assets/icon.png");
    match image::load_from_memory(bytes) {
        Ok(image) => {
            let image = image.to_rgba8();
            let size = [image.width() as usize, image.height() as usize];
            egui::IconData {
                rgba: image.into_raw(),
                width: size[0] as u32,
                height: size[1] as u32,
            }
        }
        // A broken asset must not stop the app from starting.
        Err(_) => egui::IconData {
            rgba: vec![33, 192, 99, 255],
            width: 1,
            height: 1,
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_icon_decodes_to_a_square_rgba_bitmap() {
        let icon = window_icon();
        assert_eq!(icon.width, icon.height);
        assert!(icon.width >= 64, "large enough for the taskbar");
        assert_eq!(
            icon.rgba.len(),
            (icon.width as usize) * (icon.height as usize) * 4
        );
        // The artwork is the WhatsApp green, not an empty bitmap.
        assert!(
            icon.rgba
                .as_chunks::<4>()
                .0
                .iter()
                .any(|pixel| pixel[1] > 120 && pixel[0] < 100),
            "no green pixels in the icon"
        );
    }
}
